import java.util.*;

class Solution {
  public int[] groupStrings(String[] words) {
    int n = words.length;
    int[] masks = new int[n];
    Map<Integer, Integer> first = new HashMap<>();
    for (int i = 0; i < n; i++) {
      for (char c : words[i].toCharArray()) masks[i] |= 1 << (c - 'a');
      first.putIfAbsent(masks[i], i);
    }
    // every word is in the map before any union, so each connected pair is found from both sides
    DSU d = new DSU(n);
    for (int i = 0; i < n; i++) {
      int mask = masks[i];
      d.union(i, first.get(mask));
      for (int b = 0; b < 26; b++) {
        int bit = 1 << b;
        if ((mask & bit) == 0) {
          d.union(i, first.getOrDefault(mask | bit, i)); // add a letter
          continue;
        }
        d.union(i, first.getOrDefault(mask ^ bit, i)); // delete a letter
        for (int x = 0; x < 26; x++)
          if ((mask & (1 << x)) == 0)
            d.union(i, first.getOrDefault((mask ^ bit) | (1 << x), i)); // replace a letter
      }
    }
    int groups = 0, largest = 0;
    for (int i = 0; i < n; i++)
      if (d.find(i) == i) {
        groups++;
        largest = Math.max(largest, d.size[i]);
      }
    return new int[] {groups, largest};
  }

  static class DSU {
    int[] p, size;

    DSU(int n) {
      p = new int[n];
      size = new int[n];
      for (int i = 0; i < n; i++) {
        p[i] = i;
        size[i] = 1;
      }
    }

    int find(int x) {
      while (p[x] != x) {
        p[x] = p[p[x]];
        x = p[x];
      }
      return x;
    }

    void union(int a, int b) {
      a = find(a);
      b = find(b);
      if (a == b) return;
      if (size[a] < size[b]) {
        int t = a;
        a = b;
        b = t;
      }
      p[b] = a;
      size[a] += size[b];
    }
  }
}
